def check_quizzes():
    assert 400 + 80 - 30 == 450 and 120 + 300 - 450 + 80 == 50 and 800 + 150 - 50 + 100 == 1000
    assert 2400 * 9 / 12 == 1800 and 10000 * 0.06 * 2 / 12 == 100 and 360 * 6 / 12 == 180
    assert abs(12 * 3.6 / 9 - 4.8) < 1e-9 and round(1300 * 1200 / 1500) == 1040
    assert abs((5 - 5.5) - 0.3 - (-0.8)) < 1e-9
    assert 400 + 450 - 350 == 500 and 8000 * .02 + 1500 * .1 + 500 * .4 - 130 == 380 and 20000 * .03 * 40 == 24000
    assert 50000 * .4 * .6 == 12000 and abs(90000 / 300000 * 45000 - 13500) < 1e-6 and (6400 - 400) / 4 == 1500
    assert 480 / 120 == 4 and 720 / 120 == 6 and (400 - 40) * .75 == 270 and (400 - 40 - 60) * .75 + 18 == 243
    assert round((1100 - 682 - 250) / 1100, 3) == 0.153 and 500 + 40 - 15 == 525 and 3000 + 400 - 50 - 120 - 80 == 3150
    assert 160 / 200 == 0.8 and 250 / 150 > 1.66
    assert 500 + 80 + 15 + 40 - 30 - 25 == 580 and round(850 / 90, 2) == 9.44 and 600 / 800 == 0.75
    assert 900 - 500 - 150 - 50 - 40 + 10 + 5 == 175 and 250 + 60 + 30 - 15 + 20 - 40 - 5 - 10 + 12 + 8 == 310
    assert 600 + 20 - 15 == 605 and (50 * 8 + 150 * 10) / 200 * 120 == 1140
    assert 5000 - (400 - 320) == 4920 and abs(2400 / 1250 - 1.92) < 1e-9 and 400 * .75 == 300 and 80 * .75 == 60
    assert (100 - 82) * 1000 == 18000 and (88 - 82) * 1000 == 6000 and sorted([38, 40, 45])[1] == 40
    assert 365 / (7300 / 1000) == 50 and 50 + 40 - 35 == 55 and abs(365 / (7500 / 600) - 29.2) < 1e-9
    assert round(1000 / 150, 2) == 6.67 and 960 / 8 == 120
    assert (900 - 720) * .25 == 45 and 200 + 45 - 15 == 230 and 1040 * .25 / 1000 == .26
    assert 1000 * .25 == 250 and 2000 * .25 - 400 == 100
    pv = 50 * (1 - 1.07 ** -5) / .07 + 1000 / 1.07 ** 5
    assert round(pv, 1) == 918.0 and round(pv * .07, 1) == 64.3 and round(pv * 1.07 - 50, 1) == 932.3
    assert round(250 / 160, 1) == 1.6 and abs(12 * .6 - 7.2) < 1e-9 and round(120 / 700, 3) == .171
    assert round(-70 / 30, 2) == -2.33 and round((-20 / 90) / (2 / 11), 2) == -1.22
    q = 1200 - 15 * 40 + .02 * 50000 + 8 * 10
    assert q == 1680 and round(-15 * 40 / q, 2) == -0.36 and round(.02 * 50000 / q, 2) == 0.6 and round(80 / q, 2) == 0.05
    assert 75 - 63 == 12 and 165 - 125 == 40 and 225 / 4 == 56.25 and 200 - 265 == -65 and 1000 - 800 - 500 == -300
    assert 900 + 625 + 400 + 225 + 100 == 2250 and 2 * 20 * 10 == 400 and 4900 + 300 == 5200 and (15 - 13) * 600 == 1200
    assert (120 - 40) / 4 == 20 and abs(60 * (1 - 1 / 1.5) - 20) < 1e-9 and .5 * 60 * 60 == 1800 and (50 - 10) / 2 == 20 and (30 - 10) / 2 == 10
    assert 650 + 200 + 180 + 250 - 280 == 1000 and 20 + 30 + 50 == 100 and abs(1050 / 1000 - 1.05) < 1e-9 and 22 - 20 + 35 - 40 == -3
    for k, v in Q2.items():
        assert len(v) == 5, k
        for q, o, x in v:
            assert len(o) == 3 and len(set(o)) == 3, (k, q)
    print("quiz checks ok:", len(Q2), "lessons")


if __name__ == "__main__":
    check_quizzes()
